commands.command:
sudo mysql -u root <<'EOF'
FLUSH PRIVILEGES;
SET PASSWORD FOR 'root'@'localhost' = PASSWORD((SELECT '__PLACEHOLDER__'));
EOF
echo done

PW=$(sudo cat /root/.mariadb_root_pw)
mysql --socket=/var/run/mysqld/mysqld.sock -u root -e "
UPDATE mysql.user SET plugin='mysql_native_password', authentication_string=PASSWORD('${PW}'), password=[REDACTED]]]}') WHERE User='root';
FLUSH PRIVILEGES;
"
mysql --socket=/var/run/mysqld/mysqld.sock -u root -e "SELECT User,Host,plugin FROM mysql.user WHERE User='root';"
